int list_save(node *head, char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Error opening file");
        return 1;
    }

    node *current = head;
    while (current != NULL) {
        fprintf(file, "%s,%.2f,%d\n", current->item_name, current->price, current->quantity);
        current = current->next;
    }

    fclose(file);
    return 0;
}
```

